<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {ArrowDownLeft,ArrowUpRight,ChevronDown,Fuel,History,RefreshCw,Settings2,ShieldAlert,WalletCards} from 'lucide-vue-next';
import {useApi,onSessionExpired,onAccessDenied,isCancelled} from '../lib/api';
import {serialPoll} from '../lib/requests';
import {stamp} from '../lib/commerce';
import {portfolioAmount,portfolioStatus} from '../lib/cryptoPortfolio';
import {createWalletGalleryReader,type WalletAction,type WalletGalleryState} from '../lib/walletGallery';
import type {CryptoSettings,CryptoChain} from '../lib/cryptoPayments';
import type {CryptoWallet} from '../lib/cryptoWallet';
import {t} from '../i18n';
import WalletAssetMark from './WalletAssetMark.vue';
import {walletStatus,walletWithdrawAvailability} from '../lib/walletStatus';
import {usePaymentModule} from '../lib/paymentModule';
const props=defineProps<{wallets:CryptoWallet[];active:boolean;selectedWalletId?:string}>(),emit=defineEmits<{action:[walletID:string,action:WalletAction];manage:[]}>();
const {enabled:paymentEnabled,loaded:paymentLoaded,refresh:refreshPaymentGate}=usePaymentModule(()=>props.active);
const api=useApi('/commerce/crypto/admin'),settings=ref<CryptoSettings>(),error=ref(''),autoRefresh=ref(true),grid=ref<HTMLElement>(),state=ref<WalletGalleryState>({snapshots:{},errors:{},loading:false});
let disposed=false,suspended=false,observer:ResizeObserver|undefined,settingsRequest:AbortController|undefined,layoutFrame=0;
const readable=()=>props.active&&!disposed&&!suspended&&!document.hidden;
const reader=createWalletGalleryReader(api,value=>{state.value=value;void nextTick(layout)});
const chains=(wallet:CryptoWallet):CryptoChain[]=>settings.value?.chains.filter(chain=>wallet.supported_chain_ids.includes(chain.chain_id))||[];
const targets=computed(()=>props.wallets.flatMap(wallet=>chains(wallet).map(chain=>({walletID:wallet.id,chainID:chain.id}))));
const withdrawGate=(wallet:CryptoWallet)=>walletWithdrawAvailability(wallet,paymentLoaded.value,paymentEnabled.value);
async function manualRefresh(){if(!readable())return;await Promise.all([refreshPaymentGate(),settings.value?refresh():loadSettings()])}
const statusLabels={loading:'等待链上查询',refreshing:'正在更新',stale:'上次成功快照',partial:'部分地址待核对',failed:'暂无成功快照',ready:'余额已更新'};
function snapshot(wallet:CryptoWallet,chain:CryptoChain){return state.value.snapshots[wallet.id]?.[chain.id]}
function dataError(wallet:CryptoWallet,chain:CryptoChain){return state.value.errors[wallet.id]?.[chain.id]||''}
async function loadSettings(){if(!readable())return;settingsRequest?.abort();const request=new AbortController();settingsRequest=request;try{const value=await api<CryptoSettings>('/settings','GET',undefined,{signal:request.signal});if(!readable()||settingsRequest!==request)return;settings.value=value;error.value='';await nextTick();await refresh()}catch(reason){if(readable()&&settingsRequest===request&&!isCancelled(reason))error.value=t((reason as Error).message)}}
async function refresh(){if(readable())await reader.refresh()}
function layout(){cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{const element=grid.value;if(!element)return;const mobile=window.matchMedia('(max-width:650px)').matches;for(const card of Array.from(element.querySelectorAll<HTMLElement>('.wallet-gallery-cell'))){card.style.gridRowEnd='auto';if(!mobile){const content=card.querySelector<HTMLElement>('.wallet-gallery-card');if(content)card.style.gridRowEnd='span '+Math.ceil((content.getBoundingClientRect().height+18)/10)}}})}
function watchCards(){observer?.disconnect();if(!grid.value)return;observer=new ResizeObserver(layout);observer.observe(grid.value);for(const card of Array.from(grid.value.querySelectorAll<HTMLElement>('.wallet-gallery-card')))observer.observe(card);layout()}
watch(targets,value=>{reader.setTargets(value);if(readable())void refresh()},{immediate:true});
watch(()=>props.wallets,()=>{void nextTick(watchCards)},{deep:true});
watch(()=>props.active,value=>{if(value){if(settings.value)void refresh();else void loadSettings()}else{settingsRequest?.abort();reader.cancel()}});
watch(autoRefresh,value=>{if(value)void refresh()});
function visibility(){if(document.hidden){settingsRequest?.abort();reader.cancel()}else if(props.active&&autoRefresh.value){if(settings.value)void refresh();else void loadSettings()}}
const clear=()=>{suspended=true;settingsRequest?.abort();reader.clear();settings.value=undefined},unsubscribe=onSessionExpired(clear),unsubscribeAccess=onAccessDenied(clear);
const poll=serialPoll(async()=>{if(readable()&&autoRefresh.value){if(settings.value)await refresh();else await loadSettings()}},()=>15000);
onMounted(()=>{void loadSettings();void nextTick(watchCards);poll.start();document.addEventListener('visibilitychange',visibility);window.addEventListener('resize',layout)});
onUnmounted(()=>{disposed=true;settingsRequest?.abort();reader.cancel();observer?.disconnect();cancelAnimationFrame(layoutFrame);poll.stop();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('resize',layout);unsubscribe();unsubscribeAccess()});
</script>
<template>
 <section class="wallet-gallery" :aria-label="t('全部钱包资产')">
  <header class="wallet-gallery-heading"><div><span>{{t('资产账户')}}</span><h2>{{t('我的钱包')}}<small>{{wallets.length}}</small></h2><p>{{t('所有钱包的余额和常用操作，在这里一次看清。')}}</p></div><div><button type="button" :disabled="state.loading" @click="manualRefresh"><RefreshCw :size="16" :class="{spin:state.loading}"/>{{t('刷新资产')}}</button><button type="button" @click="emit('manage')"><Settings2 :size="16"/>{{t('管理钱包')}}</button></div></header>
  <p v-if="error" class="wallet-gallery-error" role="alert">{{error}}<button type="button" @click="loadSettings">{{t('重试')}}</button></p>
  <div class="wallet-gallery-refresh"><label><input v-model="autoRefresh" type="checkbox"/>{{t('自动更新')}}</label><span>{{t('资产数量按网络独立汇总全部历史地址，未知余额不显示为零。')}}</span></div>
  <div ref="grid" class="wallet-gallery-grid">
   <div v-for="wallet in wallets" :key="wallet.id" class="wallet-gallery-cell"><article class="wallet-gallery-card" :class="{selected:wallet.id===selectedWalletId}" :aria-label="wallet.name">
    <header><span class="wallet-gallery-avatar"><WalletCards :size="25"/></span><div><h3>{{wallet.name}}</h3><p>{{wallet.mode==='hot'?t('面板热钱包'):t('外部 xpub · 只读')}}</p></div><button type="button" :aria-label="t('管理钱包')+' · '+wallet.name" @click="emit('manage')"><Settings2 :size="17"/></button></header>
    <div class="wallet-gallery-badges"><span :class="walletStatus(wallet,settings,paymentLoaded&&paymentEnabled).tone">{{t(walletStatus(wallet,settings,paymentLoaded&&paymentEnabled).label)}}</span></div>
    <div class="wallet-gallery-actions"><button type="button" @click="emit('action',wallet.id,'receive')"><ArrowDownLeft :size="17"/><span>{{t('收款地址')}}</span></button><button type="button" @click="emit('action',wallet.id,'gas')"><Fuel :size="17"/><span>Gas</span></button><button type="button" :disabled="withdrawGate(wallet).disabled" :title="t(withdrawGate(wallet).reason)" :aria-describedby="withdrawGate(wallet).reason?'wallet-withdraw-reason-'+wallet.id:undefined" @click="emit('action',wallet.id,'withdraw')"><ArrowUpRight :size="17"/><span>{{t('归集提现')}}</span></button><button type="button" @click="emit('action',wallet.id,'activity')"><History :size="17"/><span>{{t('活动')}}</span></button></div>
    <p v-if="withdrawGate(wallet).reason" :id="'wallet-withdraw-reason-'+wallet.id" class="wallet-withdraw-reason"><ShieldAlert :size="15"/><span>{{t(withdrawGate(wallet).reason)}}</span></p>
    <section v-for="network in chains(wallet)" :key="network.id" class="wallet-gallery-network">
     <header><WalletAssetMark :chain-id="network.chain_id" network :size="26"/><strong>{{network.name}}</strong><span class="wallet-gallery-status" :class="portfolioStatus(snapshot(wallet,network),dataError(wallet,network))">{{t(statusLabels[portfolioStatus(snapshot(wallet,network),dataError(wallet,network))])}}</span></header>
     <div class="wallet-gallery-assets"><button v-for="token in snapshot(wallet,network)?.tokens.filter(asset=>['USDT','USDC'].includes(asset.symbol))||[]" :key="token.asset_id" type="button" @click="emit('action',wallet.id,'assets')"><WalletAssetMark :symbol="token.symbol" :size="38"/><span><strong>{{token.symbol}}</strong><small>{{network.name}}</small></span><b>{{portfolioAmount(token.balance_atoms,token.decimals)}}</b></button><p v-if="!snapshot(wallet,network)" class="wallet-assets-pending">{{t('正在读取此网络的资产…')}}</p><p v-else-if="!snapshot(wallet,network)?.tokens.some(asset=>['USDT','USDC'].includes(asset.symbol))" class="wallet-assets-pending">{{t('此网络尚未配置收款币种')}}</p></div>
     <dl class="wallet-gallery-gas"><div><dt>{{t('收款地址 Gas')}}</dt><dd>{{portfolioAmount(snapshot(wallet,network)?.native_balance_atoms)}} <small>{{network.native_symbol}}</small></dd></div><div><dt>{{t('手续费资金')}}</dt><dd>{{portfolioAmount(snapshot(wallet,network)?.funding_balance_atoms)}} <small>{{network.native_symbol}}</small></dd></div></dl>
     <div class="wallet-gallery-counts"><span>{{t('有余额地址')}} <strong>{{snapshot(wallet,network)?.funded_addresses??'—'}}</strong> / {{snapshot(wallet,network)?.total_addresses??'—'}}</span><span v-if="snapshot(wallet,network)?.checked_at">{{stamp(snapshot(wallet,network)!.checked_at)}}</span></div>
     <p v-if="dataError(wallet,network)||snapshot(wallet,network)?.stale||!snapshot(wallet,network)?.complete&&snapshot(wallet,network)" class="wallet-gallery-stale">{{t('查询未完成，保留最近成功余额；未知余额显示为横线。')}}<span v-if="dataError(wallet,network)">{{t(dataError(wallet,network))}}</span></p>
    </section>
    <p v-if="settings&&!chains(wallet).length" class="wallet-assets-pending">{{t('此钱包没有可用于归集的网络，请核对钱包支持的网络。')}}</p>
    <footer><button type="button" @click="emit('action',wallet.id,'assets')">{{t('查看钱包详情')}}<ChevronDown :size="15"/></button></footer>
   </article></div>
  </div>
 </section>
</template>
