h:0}.wallet-gallery-card h3{font-size:18px;font-weight:620;letter-spacing:-.3px;overflow-wrap:anywhere;margin:0 0 5px}.wallet-gallery-card>header p{font-size:12px;color:var(--muted);margin:0}.wallet-gallery-card>header>button{display:grid;place-items:center;padding:8px;min-width:44px;min-height:44px;background:none;border:0;color:var(--secondary)}.wallet-gallery-badges{display:flex;flex-wrap:wrap;gap:6px;margin:17px 0}.wallet-gallery-badges span{font-size:12px;padding:4px 8px;border-radius:6px;background:var(--surface-raised);color:var(--secondary)}.wallet-gallery-badges span.ready{background:var(--accent-soft);color:var(--accent-text)}.wallet-gallery-actions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;border-bottom:1px solid var(--border);padding-bottom:20px;margin-bottom:20px}.wallet-gallery-actions button{display:flex;flex-direction:column;gap:7px;align-items:center;justify-content:center;min-height:64px;padding:9px 3px;border:0;background:var(--surface-raised);border-radius:10px;color:var(--text)}.wallet-gallery-actions button svg{color:var(--accent-text)}.wallet-gallery-actions button span{font-size:12px;white-space:nowrap}.wallet-gallery-network+.wallet-gallery-network{padding-top:22px;border-top:1px solid var(--border);margin-top:22px}.wallet-gallery-network>header{display:flex;align-items:center;gap:7px;flex-wrap:wrap;font-size:12px;margin-bottom:16px}.wallet-gallery-network>header>strong{font-size:12px;font-weight:550}.wallet-chain-dot{display:grid;place-items:center;width:23px;height:23px;font-size:12px;font-weight:600;background:var(--surface-raised);border:1px solid var(--border);border-radius:50%}.wallet-gallery-status{font-size:12px;margin-left:auto;color:var(--muted)}.wallet-gallery-status.ready{color:var(--accent-text)}.wallet-gallery-status.stale,.wallet-gallery-status.partial,.wallet-gallery-status.failed{color:var(--warning)}.wallet-gallery-assets{display:grid;gap:16px}.wallet-gallery-assets>button{display:flex;align-items:center;gap:11px;border:0;background:none;padding:0;text-align:left;min-width:0;min-height:44px}.wallet-token-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;font-size:22px;color:var(--accent-text);background:var(--accent-soft);flex-shrink:0}.wallet-token-icon.usdt{background:#e8f6ef;color:#218665}.wallet-token-icon.usdc{background:#e7f0fd;color:#3478c8}.wallet-gallery-assets>button>span:nth-child(2){display:grid;gap:4px;flex:1;min-width:0}.wallet-gallery-assets strong{font-size:13px;font-weight:550}.wallet-gallery-assets small{font-size:12px;color:var(--muted)}.wallet-gallery-assets b{font-size:17px;font-weight:600;letter-spacing:-.3px;text-align:right;overflow-wrap:anywhere;font-variant-numeric:tabular-nums;max-width:60%}.wallet-gallery-gas{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:14px;border-radius:10px;background:var(--surface-raised);margin:18px 0 0}.wallet-gallery-gas dt{font-size:12px;color:var(--muted)}.wallet-gallery-gas dd{font-size:12px;font-variant-numeric:tabular-nums;line-height:1.7;overflow-wrap:anywhere;margin:6px 0 0}.wallet-gallery-gas small{font-size:12px;color:var(--secondary)}.wallet-gallery-counts{display:flex;justify-content:space-between;flex-wrap:wrap;gap:7px;margin-top:12px;font-size:12px;color:var(--muted)}.wallet-gallery-counts strong{color:var(--secondary);font-weight:500}.wallet-gallery-stale{font-size:12px;line-height:1.8;color:var(--warning);margin:10px 0 0;overflow-wrap:anywhere}.wallet-gallery-stale span{display:block}.wallet-assets-pending{font-size:12px;line-height:1.8;color:var(--muted);margin:0;padding:5px 0}.wallet-gallery-card>footer{margin:19px 0 -5px;border-top:1px solid var(--border);padding-top:10px}.wallet-gallery-card>footer button{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;min-height:44px;border:0;background:none;font-size:12px;color:var(--secondary);padding:0}.wallet-gallery-error{font-size:12px;color:var(--danger);line-height:1.8;display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:0}.wallet-gallery-error button{min-height:44px}@media(max-width:650px){.wallet-gallery-heading{align-items:flex-start;flex-direction:column;gap:14px}.wallet-gallery-heading h2{font-size:25px}.wallet-gallery-heading>div:last-child{width:100%}.wallet-gallery-heading button{flex:1;justify-content:center}.wallet-gallery-refresh>span{line-height:1.8}.wallet-gallery-grid{grid-template-columns:1fr;grid-auto-rows:auto;row-gap:16px}.wallet-gallery-card{padding:19px;border-radius:17px}.wallet-gallery-card h3{font-size:17px}.wallet-gallery-avatar{width:44px;height:44px;border-radius:14px}.wallet-gallery-actions button{min-height:65px}.wallet-gallery-assets b{font-size:16px}}
.wallet-gallery-badges span.warning{color:var(--warning)}.wallet-gallery-assets b{font-size:24px}.wallet-gallery-gas dd{font-size:20px;font-weight:550}@media(max-width:650px){.wallet-gallery-assets b{font-size:22px}.wallet-gallery-gas dd{font-size:19px}}
.wallet-withdraw-reason{display:flex;align-items:flex-start;gap:7px;font-size:12px;line-height:1.8;color:var(--secondary);margin:-7px 0 18px}.wallet-withdraw-reason svg{flex-shrink:0;color:var(--warning);margin-top:3px}
</style>
